const c=$json.data; const prompt=`Genera exactamente ${c.question_count||5} preguntas diversas para RRHH usando EXCLUSIVAMENTE los datos suministrados. No inventes experiencias, empresas ni tecnologías. No afirmes uso profesional sin evidencia laboral. Con evidencia contextualiza con la experiencia; si es habilidad declarada pregunta por el contexto sin afirmar experiencia. Prioriza tecnologías, responsabilidades, requisitos obligatorios y faltantes. No preguntes por características protegidas ni tomes decisiones laborales. source_type solo: WORK_EXPERIENCE, DECLARED_SKILL, EDUCATION, CERTIFICATION, REQUIREMENT_VALIDATION. experience_id debe ser real o null. Devuelve solo JSON con questions.

candidate_name=${JSON.stringify(c.candidate_name)}
total_experience_years=${JSON.stringify(c.total_experience_years)}
work_experiences=${JSON.stringify(c.work_experiences)}
detected_skills=${JSON.stringify(c.detected_skills)}
declared_unverified_skills=${JSON.stringify(c.declared_unverified_skills)}
work_evidence=${JSON.stringify(c.work_evidence)}
vacancy_requirements=${JSON.stringify(c.vacancy_requirements)}
missing_requirements=${JSON.stringify(c.missing_requirements)}`; const topics=[...(c.detected_skills||[]).map(x=>x.nombre),...(c.declared_unverified_skills||[]),...(c.vacancy_requirements||[]).map(x=>x.name),...(c.missing_requirements||[])]; const evidence=(c.work_experiences||[]).flatMap(x=>(x.funciones||[]).map(value=>({experience_id:x.id,text:String(value).trim().toLowerCase()}))); return [{json:{prompt,analysis_id:c.analysis_id,valid_experience_ids:(c.work_experiences||[]).map(x=>x.id),valid_topics:topics.map(x=>String(x).trim().toLowerCase()),valid_work_evidence:evidence}}];
